#include <iostream>
#include <vector>

void insertion_sort(std::vector<int>& fish) {
    int n = fish.size();
    for (int i = 1; i < n; i++) {
        int hold = fish[i];
        int j = i - 1;
        while (j >= 0 && fish[j] > hold) {
            fish[j + 1] = fish[j];
            j--;
        }
        fish[j + 1] = hold;
    }
}

int main() {
    std::vector<int> fish = {4, 8, 1, 6, 3};
    insertion_sort(fish);
    std::cout << "理牌式：";
    for (int i = 0; i < fish.size(); i++) {
        std::cout << fish[i] << " ";
    }
    std::cout << "\n";
    return 0;
}
